"""
THE NEW CIVILIZATION - Ultra-Lightweight Hugging Face Controller
Zero Dependencies • Pure API • Maximum Revenue

This is the heart of The New Civilization - managing all AI operations
through Hugging Face APIs without any heavy local dependencies.
"""

import os
import json
import time
import logging
from datetime import datetime
from urllib.request import urlopen, Request
from urllib.parse import urlencode
from urllib.error import HTTPError, URLError

class NewCivilizationHF:
    """Ultra-lightweight Hugging Face API controller"""

    def __init__(self, token=None):
        # Load configuration
        self.config = self._load_config()
        self.hf_token = token or self.config.get('HF_TOKEN', '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')
        self.api_base = self.config.get('HF_API_BASE', 'https://api-inference.huggingface.co/models')

        # Revenue tracking
        self.revenue_target = float(self.config.get('REVENUE_TARGET_MONTHLY', 1500))
        self.current_revenue = 0.0

        # Default models for different tasks
        self.models = {
            'text_generation': 'microsoft/DialoGPT-medium',
            'text_classification': 'cardiffnlp/twitter-roberta-base-sentiment-latest',
            'summarization': 'facebook/bart-large-cnn',
            'translation': 'Helsinki-NLP/opus-mt-en-id',
            'question_answering': 'deepset/roberta-base-squad2',
            'text_embedding': 'sentence-transformers/all-MiniLM-L6-v2'
        }

        print("🌟 The New Civilization HF Controller initialized")
        print(f"💰 Revenue target: ${self.revenue_target}/month")
        print(f"🤖 Available models: {len(self.models)}")

    def _load_config(self):
        """Load configuration from environment or config file"""
        config = {}

        # Try to load from .env file
        env_file = os.path.join(os.path.dirname(__file__), '..', 'config', '.env')
        if os.path.exists(env_file):
            with open(env_file, 'r') as f:
                for line in f:
                    if '=' in line and not line.strip().startswith('#'):
                        key, value = line.strip().split('=', 1)
                        config[key] = value

        # Override with environment variables
        for key in ['HF_TOKEN', 'HF_API_BASE', 'REVENUE_TARGET_MONTHLY']:
            env_value = os.getenv(key)
            if env_value:
                config[key] = env_value

        return config

    def query_model(self, model_name, inputs, task_type="text_generation"):
        """Query Hugging Face model via API"""
        try:
            # Prepare API request
            url = f"{self.api_base}/{model_name}"
            headers = {
                'Authorization': f'Bearer {self.hf_token}',
                'Content-Type': 'application/json'
            }

            # Prepare payload based on task type
            payload = self._prepare_payload(inputs, task_type)
            data = json.dumps(payload).encode('utf-8')

            # Make API request
            req = Request(url, data=data, headers=headers)

            with urlopen(req, timeout=60) as response:
                result = json.loads(response.read().decode('utf-8'))

            # Log successful request
            self._log_request(model_name, task_type, "success")

            return {
                'success': True,
                'data': result,
                'model': model_name,
                'task': task_type,
                'timestamp': datetime.now().isoformat()
            }

        except HTTPError as e:
            error_msg = f"HTTP Error {e.code}: {e.reason}"
            self._log_request(model_name, task_type, "error", error_msg)
            return {'success': False, 'error': error_msg}

        except URLError as e:
            error_msg = f"URL Error: {e.reason}"
            self._log_request(model_name, task_type, "error", error_msg)
            return {'success': False, 'error': error_msg}

        except Exception as e:
            error_msg = f"Unexpected error: {str(e)}"
            self._log_request(model_name, task_type, "error", error_msg)
            return {'success': False, 'error': error_msg}

    def _prepare_payload(self, inputs, task_type):
        """Prepare API payload based on task type"""
        if task_type == "text_generation":
            return {"inputs": inputs}
        elif task_type == "text_classification":
            return {"inputs": inputs}
        elif task_type == "summarization":
            return {"inputs": inputs}
        elif task_type == "translation":
            return {"inputs": inputs}
        elif task_type == "question_answering":
            return {"inputs": inputs}
        else:
            return {"inputs": inputs}

    def generate_text(self, prompt, model_name=None):
        """Generate text using HF models"""
        model = model_name or self.models['text_generation']
        return self.query_model(model, prompt, "text_generation")

    def classify_text(self, text, model_name=None):
        """Classify text sentiment/category"""
        model = model_name or self.models['text_classification']
        return self.query_model(model, text, "text_classification")

    def summarize_text(self, text, model_name=None):
        """Summarize long text"""
        model = model_name or self.models['summarization']
        return self.query_model(model, text, "summarization")

    def translate_text(self, text, model_name=None):
        """Translate text"""
        model = model_name or self.models['translation']
        return self.query_model(model, text, "translation")

    def answer_question(self, question, context="", model_name=None):
        """Answer questions using context"""
        model = model_name or self.models['question_answering']
        inputs = {"question": question, "context": context}
        return self.query_model(model, inputs, "question_answering")

    def get_embedding(self, text, model_name=None):
        """Get text embeddings"""
        model = model_name or self.models['text_embedding']
        return self.query_model(model, text, "feature_extraction")

    def _log_request(self, model, task, status, error=None):
        """Log API requests for monitoring"""
        log_entry = {
            'timestamp': datetime.now().isoformat(),
            'model': model,
            'task': task,
            'status': status,
            'error': error
        }

        # Simple logging to file
        log_dir = os.path.join(os.path.dirname(__file__), '..', 'logs')
        os.makedirs(log_dir, exist_ok=True)

        log_file = os.path.join(log_dir, 'hf_requests.jsonl')
        with open(log_file, 'a') as f:
            f.write(json.dumps(log_entry) + '\\n')

    def get_stats(self):
        """Get usage statistics"""
        try:
            log_file = os.path.join(os.path.dirname(__file__), '..', 'logs', 'hf_requests.jsonl')
            if not os.path.exists(log_file):
                return {'total_requests': 0, 'successful_requests': 0, 'error_rate': 0}

            total = 0
            successful = 0

            with open(log_file, 'r') as f:
                for line in f:
                    if line.strip():
                        entry = json.loads(line)
                        total += 1
                        if entry.get('status') == 'success':
                            successful += 1

            error_rate = ((total - successful) / total * 100) if total > 0 else 0

            return {
                'total_requests': total,
                'successful_requests': successful,
                'error_rate': round(error_rate, 2)
            }

        except Exception as e:
            return {'error': f'Failed to get stats: {str(e)}'}

# Example usage
