@app.route('/')
def index():
    """Main web interface"""
    stats = hf_controller.get_stats() if hf_controller else None
    business = business_engine.get_business_dashboard() if business_engine else None

    return render_template_string(WEB_INTERFACE, stats=stats, business=business)

@app.route('/api/health')
def health_check():
    """Health check endpoint"""
    return jsonify({
        'status': 'healthy',
        'timestamp': datetime.now().isoformat(),
        'components': {
            'hf_controller': hf_controller is not None,
            'business_engine': business_engine is not None
        }
    })

@app.route('/api/generate', methods=['POST'])
def generate_text():
    """Generate text using Hugging Face models"""
    if not hf_controller:
        return jsonify({'error': 'HF Controller not initialized'}), 500

    data = request.get_json()
    if not data or 'prompt' not in data:
        return jsonify({'error': 'Prompt required'}), 400

    result = hf_controller.generate_text(data['prompt'])
    return jsonify(result)

@app.route('/api/sentiment', methods=['POST'])
def analyze_sentiment():
    """Analyze text sentiment"""
    if not hf_controller:
        return jsonify({'error': 'HF Controller not initialized'}), 500

    data = request.get_json()
    if not data or 'text' not in data:
        return jsonify({'error': 'Text required'}), 400

    result = hf_controller.classify_text(data['text'])
    return jsonify(result)

@app.route('/api/summarize', methods=['POST'])
def summarize_text():
    """Summarize text"""
    if not hf_controller:
        return jsonify({'error': 'HF Controller not initialized'}), 500

    data = request.get_json()
    if not data or 'text' not in data:
        return jsonify({'error': 'Text required'}), 400

    result = hf_controller.summarize_text(data['text'])
    return jsonify(result)

@app.route('/api/translate', methods=['POST'])
def translate_text():
    """Translate text"""
    if not hf_controller:
        return jsonify({'error': 'HF Controller not initialized'}), 500

    data = request.get_json()
    if not data or 'text' not in data:
        return jsonify({'error': 'Text required'}), 400

    result = hf_controller.translate_text(data['text'])
    return jsonify(result)

@app.route('/api/stats')
def get_stats():
    """Get system statistics"""
    stats = {}

    if hf_controller:
        stats['hf'] = hf_controller.get_stats()

    if business_engine:
        stats['business'] = business_engine.get_business_dashboard()

    return jsonify(stats)

@app.route('/api/business/clients', methods=['GET', 'POST'])
def manage_clients():
    """Manage business clients"""
    if not business_engine:
        return jsonify({'error': 'Business Engine not initialized'}), 500

    if request.method == 'POST':
        data = request.get_json()
        if not data or 'name' not in data or 'email' not in data:
            return jsonify({'error': 'Name and email required'}), 400

        client_id = business_engine.add_client(
            name=data['name'],
            email=data['email'],
            company=data.get('company', ''),
            phone=data.get('phone', ''),
            notes=data.get('notes', '')
        )

        return jsonify({'success': True, 'client_id': client_id})

    return jsonify({'clients': business_engine.clients})

@app.route('/api/business/projects', methods=['POST'])
def create_project():
    """Create new business project"""
    if not business_engine:
        return jsonify({'error': 'Business Engine not initialized'}), 500

    data = request.get_json()
    required_fields = ['client_id', 'service_type', 'description', 'estimated_price']

    if not data or not all(field in data for field in required_fields):
        return jsonify({'error': 'Missing required fields'}), 400

    project_id = business_engine.create_project(
        client_id=data['client_id'],
        service_type=data['service_type'],
        description=data['description'],
        estimated_price=data['estimated_price']
    )

    return jsonify({'success': True, 'project_id': project_id})

